def max_battle_component(grid: list[list[int]]) -> list[int]:
    m, n = len(grid), len(grid[0])
    visited = [[False] * n for _ in range(m)]
    troops = 0
    max_sz = 0
    def dfs(r, c):
        visited[r][c] = True
        sz = 1
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and not visited[nr][nc] and grid[nr][nc] == 1:
                    sz += dfs(nr, nc)
        return sz
    for r in range(m):
        for c in range(n):
            if grid[r][c] == 1 and not visited[r][c]:
                troops += 1
                max_sz = max(max_sz, dfs(r, c))
    return [troops, max_sz]
